     1→/**
     2→ * Expo config plugin — wires the native SafReaderModule into the Android build.
     3→ *
     4→ * What it does during `expo prebuild` (or EAS build):
     5→ *   1. Copies SafReaderModule.java + SafReaderPackage.java into
     6→ *      android/app/src/main/java/expo/modules/safreader/
     7→ *   2. Adds `import expo.modules.safreader.SafReaderPackage;` to MainApplication
     8→ *   3. Adds `packages.add(new SafReaderPackage());` to getPackages()
     9→ *
    10→ * React Native's autolinking does NOT pick up local Java modules unless they
    11→ * have an expo-module.config.json wired through expo-modules-core, so we
    12→ * register the package manually here.
    13→ */
    14→const { withMainApplication, withDangerousMod } = require('@expo/config-plugins');
    15→const path = require('path');
    16→const fs = require('fs');
    17→
    18→const JAVA_SRC_DIR = path.join(__dirname, '..', 'modules', 'saf-reader', 'android', 'src', 'main', 'java');
    19→
    20→const JAVA_FILES = [
    21→  'expo/modules/safreader/SafReaderModule.java',
    22→  'expo/modules/safreader/SafReaderPackage.java',
    23→];
    24→
    25→/**
    26→ * Copy the Java source files into the generated android project.
    27→ */
    28→function withSafReaderJavaSources(config) {
    29→  return withDangerousMod(config, [
    30→    'android',
    31→    (config) => {
    32→      const androidJavaSrcDir = path.join(
    33→        config.modRequest.projectRoot,
    34→        'android',
    35→        'app',
    36→        'src',
    37→        'main',
    38→        'java',
    39→      );
    40→
    41→      for (const relPath of JAVA_FILES) {
    42→        const src  = path.join(JAVA_SRC_DIR, relPath);
    43→        const dest = path.join(androidJavaSrcDir, relPath);
    44→        const destDir = path.dirname(dest);
    45→
    46→        if (!fs.existsSync(destDir)) {
    47→          fs.mkdirSync(destDir, { recursive: true });
    48→        }
    49→
    50→        if (fs.existsSync(src)) {
    51→          fs.copyFileSync(src, dest);
    52→        } else {
    53→          console.warn(`[with-saf-reader] Source file not found: ${src}`);
    54→        }
    55→      }
    56→
    57→      return config;
    58→    },
    59→  ]);
    60→}
    61→
    62→/**
    63→ * Register SafReaderPackage in MainApplication.java/kt so React Native loads it.
    64→ *
    65→ * Handles both Java (.java) and Kotlin (.kt) MainApplication files, which
    66→ * Expo generates depending on the template version.
    67→ */
    68→function withSafReaderMainApplication(config) {
    69→  return withMainApplication(config, (config) => {
    70→    let contents = config.modResults.contents;
    71→
    72→    // Idempotent — don't add twice.
    73→    if (contents.includes('SafReaderPackage')) return config;
    74→
    75→    const isKotlin = config.modResults.language === 'kt';
    76→
    77→    if (isKotlin) {
    78→      // Kotlin MainApplication
    79→      contents = contents.replace(
    80→        /(import com\.facebook\.react\.ReactApplication)/,
    81→        'import expo.modules.safreader.SafReaderPackage\n$1',
    82→      );
    83→      // Kotlin getPackages(): add before `return packages`
    84→      contents = contents.replace(
    85→        /(val packages = PackageList\(this\)\.packages)/,
    86→        '$1\n      packages.add(SafReaderPackage())',
    87→      );
    88→      // Fallback pattern used by newer Expo Kotlin templates
    89→      if (!contents.includes('SafReaderPackage()')) {
    90→        contents = contents.replace(
    91→          /(return packages)/,
    92→          'packages.add(SafReaderPackage())\n      $1',
    93→        );
    94→      }
    95→    } else {
    96→      // Java MainApplication
    97→      contents = contents.replace(
    98→        /(import com\.facebook\.react\.ReactApplication;)/,
    99→        '$1\nimport expo.modules.safreader.SafReaderPackage;',
   100→      );
   101→      // Standard Expo Java template pattern
   102→      contents = contents.replace(
   103→        /(List<ReactPackage> packages = new PackageList\(this\)\.getPackages\(\);)/,
   104→        '$1\n      packages.add(new SafReaderPackage());',
   105→      );
   106→      // Fallback: older templates use `return packages;` directly
   107→      if (!contents.includes('new SafReaderPackage()')) {
   108→        contents = contents.replace(
   109→          /(return packages;)/,
   110→          'packages.add(new SafReaderPackage());\n      $1',
   111→        );
   112→      }
   113→    }
   114→
   115→    config.modResults.contents = contents;
   116→    return config;
   117→  });
   118→}
   119→
   120→function withSafReader(config) {
   121→  config = withSafReaderJavaSources(config);
   122→  config = withSafReaderMainApplication(config);
   123→  return config;
   124→}
   125→
   126→module.exports = withSafReader;
