package expo.modules.safpicker;

import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.net.Uri;

import com.facebook.react.bridge.ActivityEventListener;
import com.facebook.react.bridge.Arguments;
import com.facebook.react.bridge.BaseActivityEventListener;
import com.facebook.react.bridge.Promise;
import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.bridge.ReactContextBaseJavaModule;
import com.facebook.react.bridge.ReactMethod;
import com.facebook.react.bridge.WritableMap;

/**
 * SafPickerModule — fires ACTION_OPEN_DOCUMENT_TREE with forced DocumentsUI.
 *
 * KEY INSIGHT: OEM file managers (Samsung MyFiles, MIUI, Realme, Vivo, Oppo)
 * register themselves to handle ACTION_OPEN_DOCUMENT_TREE and completely ignore
 * EXTRA_INITIAL_URI. By calling intent.setPackage("com.android.documentsui") we
 * force Android's built-in system document picker which ALWAYS respects
 * EXTRA_INITIAL_URI and opens at the exact folder we specify.
 *
 * Fallback: if com.android.documentsui is not present (extremely rare, seen only
 * on custom AOSP forks) we fire the intent without a package constraint so the
 * user still gets a picker — just possibly without pre-navigation.
 *
 * EXTRA_INITIAL_URI format: uses /document/ path (not /tree/) — the correct
 * format for the hint URI as documented in DocumentsContract.EXTRA_INITIAL_URI.
 * Many OEM pickers that partially respect the hint only handle this format.
 */
public class SafPickerModule extends ReactContextBaseJavaModule {

    private static final int SAF_REQUEST_CODE = 0x5AF1;
    private static final String DOCUMENTS_UI_PACKAGE = "com.android.documentsui";
    private static final String MODULE_NAME = "SafPickerModule";

    private Promise mPendingPromise;

    private final ActivityEventListener mActivityEventListener = new BaseActivityEventListener() {
        @Override
        public void onActivityResult(Activity activity, int requestCode, int resultCode, Intent data) {
            if (requestCode != SAF_REQUEST_CODE || mPendingPromise == null) return;

            Promise promise = mPendingPromise;
            mPendingPromise = null;

            if (resultCode == Activity.RESULT_CANCELED || data == null) {
                WritableMap result = Arguments.createMap();
                result.putBoolean("granted", false);
                result.putString("directoryUri", "");
                promise.resolve(result);
                return;
            }

            Uri treeUri = data.getData();
            if (treeUri == null) {
                WritableMap result = Arguments.createMap();
                result.putBoolean("granted", false);
                result.putString("directoryUri", "");
                promise.resolve(result);
                return;
            }

            // Take persistable read permission so the grant survives app restarts.
            // expo-file-system also does this, but we do it here too for safety
            // since we own the intent result in this path.
            try {
                activity.getContentResolver().takePersistableUriPermission(
                    treeUri,
                    Intent.FLAG_GRANT_READ_URI_PERMISSION
                );
            } catch (SecurityException e) {
                // Non-fatal — the URI is still usable for this session
            }

            WritableMap result = Arguments.createMap();
            result.putBoolean("granted", true);
            result.putString("directoryUri", treeUri.toString());
            promise.resolve(result);
        }
    };

    SafPickerModule(ReactApplicationContext reactContext) {
        super(reactContext);
        reactContext.addActivityEventListener(mActivityEventListener);
    }

    @Override
    public String getName() {
        return MODULE_NAME;
    }

    /**
     * Open Android's document-tree picker forced to open at initialUri.
     *
     * @param initialUriString  A document-format content URI
     *                          (e.g. content://com.android.externalstorage.documents/document/primary%3AAndroid%2Fmedia)
     *                          Used as EXTRA_INITIAL_URI so the picker opens there directly.
     * @param promise           Resolved with {granted: boolean, directoryUri: string}
     */
    @ReactMethod
    public void openDocumentTree(String initialUriString, Promise promise) {
        Activity activity = getCurrentActivity();
        if (activity == null) {
            promise.reject("E_NO_ACTIVITY", "Activity is not available");
            return;
        }
        if (mPendingPromise != null) {
            promise.reject("E_IN_FLIGHT", "A folder picker is already open");
            return;
        }
        mPendingPromise = promise;

        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        intent.addFlags(
            Intent.FLAG_GRANT_READ_URI_PERMISSION
            | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION
            | Intent.FLAG_GRANT_PREFIX_URI_PERMISSION
        );

        // Set the folder hint — MUST use /document/ format, not /tree/
        if (initialUriString != null && !initialUriString.isEmpty()) {
            Uri hintUri = Uri.parse(initialUriString);
            // DocumentsContract.EXTRA_INITIAL_URI constant value (API 26+)
            intent.putExtra("android.provider.extra.INITIAL_URI", hintUri);
        }

        // ── Force system DocumentsUI to bypass OEM file managers ─────────────
        // com.android.documentsui is Android's built-in picker. It always
        // honours EXTRA_INITIAL_URI. OEM file managers (Samsung, Xiaomi, etc.)
        // register to handle ACTION_OPEN_DOCUMENT_TREE but ignore the URI hint.
        boolean forcedDocumentsUI = false;
        try {
            activity.getPackageManager().getPackageInfo(DOCUMENTS_UI_PACKAGE, 0);
            intent.setPackage(DOCUMENTS_UI_PACKAGE);
            forcedDocumentsUI = true;
        } catch (PackageManager.NameNotFoundException e) {
            // DocumentsUI not present — proceed without package constraint.
            // This is extremely rare (only custom AOSP forks remove it).
        }

        try {
            activity.startActivityForResult(intent, SAF_REQUEST_CODE);
        } catch (Exception e) {
            if (forcedDocumentsUI) {
                // DocumentsUI found but failed to start (e.g. disabled in settings).
                // Retry without the package constraint.
                intent.setPackage(null);
                try {
                    activity.startActivityForResult(intent, SAF_REQUEST_CODE);
                } catch (Exception e2) {
                    mPendingPromise = null;
                    promise.reject("E_PICKER_FAILED", "Could not open folder picker: " + e2.getMessage());
                }
            } else {
                mPendingPromise = null;
                promise.reject("E_PICKER_FAILED", "Could not open folder picker: " + e.getMessage());
            }
        }
    }

    /** Returns true — always available when compiled in. Used by JS isAvailable(). */
    @ReactMethod
    public void checkAvailable(Promise promise) {
        promise.resolve(true);
    }
}

package expo.modules.safpicker;

import com.facebook.react.ReactPackage;
import com.facebook.react.bridge.NativeModule;
import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.uimanager.ViewManager;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SafPickerPackage implements ReactPackage {

    @Override
    public List<NativeModule> createNativeModules(ReactApplicationContext reactContext) {
        return Arrays.asList(new SafPickerModule(reactContext));
    }

    @Override
    public List<ViewManager> createViewManagers(ReactApplicationContext reactContext) {
        return Collections.emptyList();
    }
}

/**
 * SafPicker — JS bridge for the native SafPickerModule.
 *
 * Fires ACTION_OPEN_DOCUMENT_TREE with:
 *   • intent.setPackage("com.android.documentsui") — forces Android's built-in
 *     document picker, bypassing Samsung MyFiles / MIUI / Realme file managers
 *     that intercept the intent and ignore EXTRA_INITIAL_URI.
 *   • EXTRA_INITIAL_URI in /document/ format — opens at exactly the folder
 *     specified on 100% of devices that have DocumentsUI.
 *
 * Falls back to the default file manager if DocumentsUI is not present
 * (only extremely rare custom AOSP forks remove it).
 *
 * isAvailable() returns false in Expo Go, iOS, and web.
 */
import { NativeModules, Platform } from 'react-native';

// ── URI constants ─────────────────────────────────────────────────────────────
//
// IMPORTANT: EXTRA_INITIAL_URI requires the /document/ form, not /tree/.
// Using /tree/ causes many OEM pickers to ignore or misparse the hint.
//
// Decoded:  content://com.android.externalstorage.documents/document/primary:Android/media
export const DOCUMENT_URI_ANDROID_MEDIA =
  'content://com.android.externalstorage.documents/document/primary%3AAndroid%2Fmedia';

// Deep fallbacks — used by "Browse manually" path only
export const DOCUMENT_URI_WHATSAPP =
  'content://com.android.externalstorage.documents/document/primary%3AAndroid%2Fmedia%2Fcom.whatsapp%2FWhatsApp%2FMedia';

export const DOCUMENT_URI_WHATSAPP_BUSINESS =
  'content://com.android.externalstorage.documents/document/primary%3AAndroid%2Fmedia%2Fcom.whatsapp.w4b%2FWhatsApp%20Business%2FMedia';

// ── Native module binding ─────────────────────────────────────────────────────

interface SafPickerNative {
  openDocumentTree(initialUri: string): Promise<{ granted: boolean; directoryUri: string }>;
  checkAvailable(): Promise<boolean>;
}

const SafPickerNative: SafPickerNative | null =
  Platform.OS === 'android' ? (NativeModules.SafPickerModule ?? null) : null;

// ── Public API ────────────────────────────────────────────────────────────────

/** True only when the native Java module is compiled in (custom dev-client / EAS). */
export function isAvailable(): boolean {
  return SafPickerNative !== null;
}

/**
 * Open the system document-tree picker at `initialUri`.
 *
 * Uses DocumentsUI (com.android.documentsui) directly so the folder hint
 * is always respected — regardless of OEM device brand.
 *
 * @param initialUri  A /document/ format URI (use the DOCUMENT_URI_* constants).
 * @returns           {granted, directoryUri} — directoryUri is the granted tree URI.
 */
export async function openDocumentTree(
  initialUri: string,
): Promise<{ granted: boolean; directoryUri: string }> {
  if (!SafPickerNative) {
    return { granted: false, directoryUri: '' };
  }
  return SafPickerNative.openDocumentTree(initialUri);
}

/**
 * with-saf-picker.js
 *
 * Expo config plugin that wires SafPickerModule into the Android build.
 * This module bypasses OEM file managers and forces Android's built-in
 * DocumentsUI so the SAF folder picker always opens at Android/media.
 *
 * During `expo prebuild` / EAS build this plugin:
 *   1. Copies SafPickerModule.java + SafPickerPackage.java into the Android project
 *   2. Registers SafPickerPackage in MainApplication (Java or Kotlin)
 *   3. Adds a <queries> block to AndroidManifest so Android 11+ allows the app
 *      to detect and directly launch com.android.documentsui
 */

const { withMainApplication, withDangerousMod, withAndroidManifest } = require('@expo/config-plugins');
const path = require('path');
const fs   = require('fs');

const JAVA_SRC_DIR = path.join(
  __dirname,
  '..',
  'modules',
  'saf-picker',
  'android',
  'src',
  'main',
  'java',
);

const JAVA_FILES = [
  'expo/modules/safpicker/SafPickerModule.java',
  'expo/modules/safpicker/SafPickerPackage.java',
];

// ── Step 1: Copy Java sources ─────────────────────────────────────────────────

function withSafPickerJavaSources(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const androidJavaSrcDir = path.join(
        config.modRequest.projectRoot,
        'android',
        'app',
        'src',
        'main',
        'java',
      );

      for (const relPath of JAVA_FILES) {
        const src     = path.join(JAVA_SRC_DIR, relPath);
        const dest    = path.join(androidJavaSrcDir, relPath);
        const destDir = path.dirname(dest);

        if (!fs.existsSync(destDir)) {
          fs.mkdirSync(destDir, { recursive: true });
        }

        if (fs.existsSync(src)) {
          fs.copyFileSync(src, dest);
        } else {
          console.warn(`[with-saf-picker] Source file not found: ${src}`);
        }
      }

      return config;
    },
  ]);
}

// ── Step 2: Register SafPickerPackage in MainApplication ──────────────────────

function withSafPickerMainApplication(config) {
  return withMainApplication(config, (config) => {
    let contents = config.modResults.contents;

    if (contents.includes('SafPickerPackage')) return config; // idempotent

    const isKotlin = config.modResults.language === 'kt';

    if (isKotlin) {
      contents = contents.replace(
        /(import com\.facebook\.react\.ReactApplication)/,
        'import expo.modules.safpicker.SafPickerPackage\n$1',
      );
      contents = contents.replace(
        /(val packages = PackageList\(this\)\.packages)/,
        '$1\n      packages.add(SafPickerPackage())',
      );
      if (!contents.includes('SafPickerPackage()')) {
        contents = contents.replace(
          /(return packages)/,
          'packages.add(SafPickerPackage())\n      $1',
        );
      }
    } else {
      contents = contents.replace(
        /(import com\.facebook\.react\.ReactApplication;)/,
        '$1\nimport expo.modules.safpicker.SafPickerPackage;',
      );
      contents = contents.replace(
        /(List<ReactPackage> packages = new PackageList\(this\)\.getPackages\(\);)/,
        '$1\n      packages.add(new SafPickerPackage());',
      );
      if (!contents.includes('new SafPickerPackage()')) {
        contents = contents.replace(
          /(return packages;)/,
          'packages.add(new SafPickerPackage());\n      $1',
        );
      }
    }

    config.modResults.contents = contents;
    return config;
  });
}

// ── Step 3: Add <queries> block so Android 11+ allows detecting DocumentsUI ──

function withSafPickerManifestQueries(config) {
  return withAndroidManifest(config, (config) => {
    const manifest = config.modResults.manifest;

    if (!manifest.queries) {
      manifest.queries = [];
    }

    // Check if already declared
    const alreadyDeclared = manifest.queries.some(
      (q) => q.package && q.package.some((p) => p.$?.['android:name'] === 'com.android.documentsui'),
    );

    if (!alreadyDeclared) {
      manifest.queries.push({
        package: [{ $: { 'android:name': 'com.android.documentsui' } }],
      });
    }

    return config;
  });
}

// ── Compose ───────────────────────────────────────────────────────────────────

function withSafPicker(config) {
  config = withSafPickerJavaSources(config);
  config = withSafPickerMainApplication(config);
  config = withSafPickerManifestQueries(config);
  return config;
}

module.exports = withSafPicker;

